    "description": "يعد مسار توربو معلم الجذب المثير المميز في عالم فيراري، حيث ينطلق بالركاب بزاوية عمودية 90 درجة إلى ارتفاع مذهل يبلغ 62 متراً قبل الانحدار في سقوط حر مثير بانعدام الجاذبية. يحاكي نظام الإطلاق التسارع الانفجاري لسيارة سباق الفورمولا 1، وعندما تنطلق عبر السقف، ستشاهد مناظر بانورامية خلابة لجزيرة ياس. على الرغم من أن الرحلة قصيرة، إلا أن شدتها تترك انطباعاً دائماً، مما يجعلها ثاني أكثر ألعاب الإثارة شعبية بعد فورمولا روسا. يجب أن يكون طول الركاب 130 سم على الأقل، ويجب على الأشخاص الذين يعانون من أمراض القلب تجنب هذا الجذب. قد تكون أوقات الانتظار طويلة، لذا احضر عند الافتتاح مباشرة أو فكر في الحصول على تذكرة المرور السريع. مع أحزمة الأمان والأحزمة الآمنة، يمكنك تجربة سرعة فيراري الديناميكية بأمان. إذا كنت مستعداً للشعور بالإثارة، فهذا هو التحدي الخاص بك.",
    "duration": "4-6 ساعات",
    "admission": "AED 295-345",
