    "description": "بيت الحرفيين هو مركز للحرف التقليدية يقع داخل قصر الحصن، حيث يمكنك اكتشاف وتجربة الحرف اليدوية الإماراتية العريقة. انغمس في ورش العمل التي يقودها حرفيون إماراتيون متمرسون، وتعلم السدو (النسيج البدوي) وصناعة الدلة (إبريق القهوة) والتلي (تطريز الخيوط الذهبية)، واصطحب معك إبداعك الخاص المصنوع يدوياً. يعمل هذا المركز كجزء من التزام الإمارات بالحفاظ على التراث الثقافي غير المادي للأجيال الحديثة، ويقدم قيمة تعليمية استثنائية. مع درجة تقييم 4.33، يستجيب الزوار بحماس لهذه التجربة الفريدة. قم بزيارته إلى جانب قصر الحصن للحصول على رؤى عميقة حول الثقافة الإماراتية. إذا كنت تحب صنع شيء بيديك، فهذا أمر لا بد منه.",
