    "description": "متحف اللوفر أبوظبي هو تحفة معمارية عالمية صممها جان نوفيل، ويتميز بقبته الأيقونية المعروفة باسم 'مطر الضوء'. تتكون القبة الضخمة من 8600 نجمة معدنية متداخلة، تخلق أنماطاً ساحرة من الضوء على الأرضيات والجدران - وهي عمل فني بحد ذاته. تستلهم العمارة، التي تبدو وكأنها تطفو على الماء، من المشربية العربية التقليدية، مع هيكل مفتوح حيث يطل البحر والسماء من بين المباني. انضم إلى جولة معمارية لاكتشاف القصص الخفية وفلسفة التصميم وراء هذا الهيكل الاستثنائي. بتقييم 4.59، تجعل العمارة وحدها هذا المكان يستحق الزيارة، حيث يقدم تجربة لا تُنسى لعشاق الفن والعمارة.",
    "duration": "2-3 ساعة",
    "admission": "성인 AED 63, 18세 이하 무료",
    "hours": "화-목 10:00-18:30, 금-일 10:00-20:30",
    "closed": "월요일",
