    "description": "سي وورلد جزيرة ياس، الذي افتتح في عام 2023، هو أحدث مدينة ملاهي في جزيرة ياس وأول سي وورلد يعمل بدون حيتان الأوركا. اقترب من الدلافين وأسود البحر والحياة البحرية المتنوعة من خلال المعارض التفاعلية والعروض الحية الآسرة التي تمزج بين التعليم والترفيه. يعلم عالم المحيط الواحد الزوار عن الترابط البيئي والأهمية الحيوية للحفاظ على البيئة، بينما توفر أفعوانية مانتا إثارة أكثر من المتوقع - تستحق التحدي بالتأكيد! مع حجم الأكواريوم المذهل ومجموعة الحياة البحرية المتنوعة، إنه المكان المثالي لإثارة افتتان الأطفال بمخلوقات المحيط.",
