        "العروض المتعددة المجدولة على مدار اليوم تتطلب من الزوار التنقل بين الأماكن مما يحافظ على مستويات نشاط معتدلة خلال الزيارات.",
        "تجارب الإطعام والتفاعل مع الحيوانات توفر فرص مشاركة نشطة تتجاوز المراقبة السلبية لعروض الحياة البحرية.",
