    "description": "يمثل نادي UFC الرياضي المركز الرياضي الرسمي لعلامة UFC الشهيرة عالمياً، ويقدم تدريباً شاملاً في فنون القتال المختلطة (MMA) إلى جانب برامج لياقة متنوعة. من دروس الكيك بوكسينغ والجوجيتسو البرازيلية والمواي تاي إلى التدريب التقليدي بالأوزان والكارديو وجلسات اللياقة الجماعية، اكتشف مجموعة واسعة من خيارات التمارين. تحت إشراف مدربين خبراء، تحدى نفسك بتخصصات جديدة في مرافق حديثة ومصانة بشكل لا تشوبه شائبة. بتقييم 4.4، يشيد الزوار بخبرة المدربين وجودة المرافق. إذا كنت لا تريد أن تفوت روتين التمارين الخاص بك أثناء السفر، فهذا هو وجهتك.",
    "duration": "1-2 ساعة",
