    "description": "اكتسب عالم وارنر براذرز سمعته ليس بسبب الأفعوانيات ولكن بسبب مجموعة ألعاب الظلام، التي تعتبر من بين الأفضل في العالم. باتمان: رحلة الفارس، مسرح طيران رباعي الأبعاد، يستخدم تقنية مشابهة لرحلة هاري بوتر المحرمة بينما يحظى بإشادة لتفوقه عليها. رابطة العدالة: هجوم عالم الحرب يقدم لعبة إطلاق نار مظلمة قابلة للمقارنة مع سبايدر مان من يونيفرسال. الفانوس الأخضر: أوديسة المجرة يمثل مسرحاً للطيران رباعي الأبعاد من الدرجة الأولى، بينما ثورة ريدلر تقدم أفعوانية دوارة مع طابع استثنائي. بيت الجوكر الترفيهي يوفر معلم جذب للمشي مخيف قليلاً ولكنه مناسب للعائلة. التنفيذ الموضوعي لكل لعبة متميز جداً بحيث تكشف الرحلات المتعددة عن اكتشافات جديدة. صنف أحد المراجعين باتمان: رحلة الفارس ضمن 'أفضل 3 ألعاب مظلمة في العالم' وركبها أربع مرات في يوم واحد.",
